from cethosweb_i18n_namespaces ns
cross join (values
  ('meta.title', 'भाषा एवं शोध पैनल | सशुल्क स्वास्थ्य शोध | Cethos'),
  ('meta.description', 'Cethos भाषा एवं शोध पैनल से जुड़ें: मातृभाषी वक्ताओं और मरीज़ों के साथ सशुल्क ऑनलाइन साक्षात्कार और फ़ोकस समूह, जो अनूदित स्वास्थ्य प्रश्नावलियों को अधिक स्पष्ट बनाते हैं। चिकित्सीय परिणाम आकलनों के लिए भाषाई सत्यापन और संज्ञानात्मक डीब्रीफ़िंग, 150+ भाषाओं में।'),
  ('hero.breadcrumb_home', 'मुखपृष्ठ'),
  ('hero.breadcrumb', 'शोध पैनल'),
  ('hero.title', 'Cethos भाषा एवं शोध पैनल'),
  ('hero.subtitle', 'दुनिया भर के मातृभाषी वक्ताओं और मरीज़ों के साथ सशुल्क ऑनलाइन शोध सत्र — हर भाषा में स्वास्थ्य संबंधी जानकारी को अधिक स्पष्ट बनाने में मदद करते हुए।'),
  ('hero.cta_join', 'पैनल से जुड़ें'),
  ('hero.cta_learn', 'यह कैसे काम करता है'),
  ('what.title', 'हम क्या करते हैं'),
  ('what.p1', 'जब कोई स्वास्थ्य प्रश्नावली अनूदित की जाती है, तो किसी को यह जाँचना होता है कि मरीज़ उसे वास्तव में समझते हैं या नहीं — कि हर प्रश्न स्पष्ट है, स्वाभाविक है, और हर भाषा में उसका एक ही अर्थ निकलता है। इस प्रक्रिया को भाषाई सत्यापन (linguistic validation) कहते हैं, और इसके केंद्र में होने वाले साक्षात्कारों को संज्ञानात्मक डीब्रीफ़िंग (cognitive debriefing) कहते हैं।'),
  ('what.p2', 'Cethos ये सत्र उन चिकित्सीय परिणाम आकलनों के लिए आयोजित करता है, जिनका उपयोग दुनिया भर के चिकित्सा शोध में होता है। हमारा शोध पैनल मातृभाषी वक्ताओं और मरीज़ों का वह समुदाय है जो इसे संभव बनाता है — और जिन्हें हर पूर्ण किए गए सत्र के लिए मानदेय दिया जाता है।'),
  ('what.card1_title', 'साक्षात्कार एवं फ़ोकस समूह'),
  ('what.card1_body', 'एक-से-एक साक्षात्कार और छोटे समूह सत्र, जो ऑनलाइन वीडियो कॉल या फ़ोन के ज़रिए आयोजित किए जाते हैं। अधिकांश सत्र 30–90 मिनट के होते हैं और आपकी भाषा में एक अनुभवी साक्षात्कारकर्ता द्वारा संचालित किए जाते हैं।'),
  ('what.card2_title', 'वास्तविक जीवन में स्पष्टता की जाँच'),
  ('what.card2_body', 'आप अनूदित स्वास्थ्य प्रश्नों को पढ़ते हैं और अपने शब्दों में हमें बताते हैं कि उनका क्या अर्थ है। कोई उत्तर सही या ग़लत नहीं होता — एक मातृभाषी वक्ता के रूप में आपकी समझ ही ठीक वह चीज़ है जिसे हम मापते हैं।'),
  ('what.card3_title', 'आपके समय का भुगतान'),
  ('what.card3_body', 'हर पूर्ण किए गए सत्र के लिए मानदेय मिलता है, जो बुकिंग से पहले तय किया जाता है और आपकी स्थानीय मुद्रा में PayPal या बैंक ट्रांसफ़र के ज़रिए, सामान्यतः 30 दिनों के भीतर भुगतान किया जाता है।'),
  ('how.title', 'यह कैसे काम करता है'),
  ('how.step1_title', 'पैनल से जुड़ें'),
  ('how.step1_body', 'अपनी भाषा में एक बार साइन अप करें। इसमें लगभग 5 मिनट लगते हैं — हमें बताएँ कि आपकी मातृभाषा कौन-सी है, आप कहाँ रहते हैं, और आप कब उपलब्ध रहते हैं।'),
  ('how.step2_title', 'आमंत्रण पाएँ'),
  ('how.step2_body', 'जब कोई अध्ययन आपकी भाषा और देश से मेल खाता है, तो हम आपको एक व्यक्तिगत आमंत्रण ईमेल करते हैं, जिसमें मानदेय और सत्र की अवधि पहले से स्पष्ट रहती है।'),
  ('how.step3_title', 'समय बुक करें'),
  ('how.step3_body', 'अपने लिए सुविधाजनक समय चुनें — समय आपके अपने टाइमज़ोन में दिखाए जाते हैं। पुष्टि, मीटिंग लिंक और अनुस्मारक सभी अपने-आप पहुँच जाते हैं।'),
  ('how.step4_title', 'भाग लें एवं भुगतान पाएँ'),
  ('how.step4_body', 'सत्र में शामिल हों, अपना नज़रिया साझा करें, और अपना मानदेय पाएँ। किसी तैयारी या विशेष जानकारी की आवश्यकता नहीं है।'),
  ('how.note', 'भाग लेना हमेशा स्वैच्छिक होता है — आप किसी भी आमंत्रण को अस्वीकार कर सकते हैं या बुकिंग रद्द कर सकते हैं, और इससे भविष्य के आमंत्रणों पर कभी कोई असर नहीं पड़ता।'),
  ('who.title', 'हम किसकी तलाश में हैं'),
  ('who.intro', 'यह पैनल दुनिया भर के लिए खुला है और हर हफ़्ते बढ़ता जा रहा है। तीन तरह के सदस्य हमारे अध्ययनों को संभव बनाते हैं:'),
  ('who.item1_title', 'मातृभाषी वक्ता'),
  ('who.item1_body', 'हर पृष्ठभूमि के वयस्क जो हमारे किसी अध्ययन-भाषा को मातृभाषा के रूप में बोलते हैं। किसी चिकित्सा या भाषा-उद्योग के अनुभव की ज़रूरत नहीं है — रोज़मर्रा का नज़रिया ही असली बात है।'),
  ('who.item2_title', 'मरीज़'),
  ('who.item2_body', 'कई अध्ययन किसी विशेष स्वास्थ्य स्थिति के साथ जी रहे लोगों पर केंद्रित होते हैं, क्योंकि जिन प्रश्नावलियों की जाँच की जा रही होती है वे उन्हीं के अनुभव के बारे में होती हैं। स्वास्थ्य संबंधी जानकारी साझा करना हमेशा वैकल्पिक और सहमति-आधारित होता है।'),
  ('who.item3_title', 'साक्षात्कारकर्ता एवं सामुदायिक भर्तीकर्ता'),
  ('who.item3_body', 'अनुभवी संज्ञानात्मक-डीब्रीफ़िंग साक्षात्कारकर्ता, और मज़बूत सामुदायिक नेटवर्क वाले लोग जो प्रति-प्रतिभागी मानदेय पर प्रतिभागियों का परिचय करा सकते हैं।'),
  ('roadmap.title', 'यह कार्यक्रम किस दिशा में बढ़ रहा है'),
  ('roadmap.p1', 'हमारे भाषाई सत्यापन अध्ययन 150+ भाषाओं में चलते हैं, और हम पैनल को उसी के अनुरूप विकसित कर रहे हैं — एक दीर्घकालिक शोध समुदाय के रूप में:'),
  ('roadmap.item1', 'और अधिक भाषाएँ एवं देश — जिनमें क्षेत्रीय रूप भी शामिल हैं, जैसे स्पेन की स्पेनिश बनाम लैटिन अमेरिका की स्पेनिश'),
  ('roadmap.item2', 'विभिन्न रोग क्षेत्रों में और अधिक मरीज़-अध्ययन, मधुमेह और कैंसर से लेकर दुर्लभ रोगों तक'),
  ('roadmap.item3', 'एक-से-एक साक्षात्कारों के साथ-साथ फ़ोकस समूह, जिनके सत्र विभिन्न टाइमज़ोन में निर्धारित किए जाते हैं'),
  ('roadmap.item4', 'तेज़, अधिक निष्पक्ष मानदेय भुगतान और आपकी अपनी भाषा में एक सहज बुकिंग अनुभव'),
  ('trust.title', 'आपका डेटा, आपकी पसंद'),
  ('trust.p1', 'आप जो जानकारी साझा करते हैं उसे हम केवल इसलिए संग्रहीत करते हैं ताकि आपको उपयुक्त अध्ययनों से मिला सकें और उनके बारे में आपसे संपर्क कर सकें। हम आपका डेटा कभी नहीं बेचते।'),
  ('trust.p2', 'स्वास्थ्य संबंधी जानकारी वैकल्पिक है, आपकी स्पष्ट सहमति से संग्रहीत की जाती है, और अनुरोध पर किसी भी समय हटाई जा सकती है।'),
  ('trust.p3', 'कार्यक्रम या अपने डेटा के बारे में कोई सवाल? हमें lv@cethos.com पर लिखें।'),
  ('cta.title', 'भाग लेने के लिए तैयार हैं?'),
  ('cta.body', 'साइन अप करने में लगभग 5 मिनट लगते हैं, और हम आपसे केवल तभी संपर्क करेंगे जब कोई अध्ययन वास्तव में आपसे मेल खाता हो।'),
  ('cta.button', 'शोध पैनल से जुड़ें'),
  ('cta.sponsor_title', 'कोई भाषाई सत्यापन अध्ययन चला रहे हैं?'),
  ('cta.sponsor_body', 'प्रायोजकों एवं CRO के लिए: हम 150+ भाषाओं में भर्ती करते हैं, समय-सारणी बनाते हैं और साक्षात्कार लेते हैं, अनुभवी संज्ञानात्मक-डीब्रीफ़िंग साक्षात्कारकर्ताओं और आद्योपांत समन्वय के साथ।'),
  ('cta.sponsor_button', 'हमारी टीम से बात करें')
) as v(key, value)
where ns.name = 'research'
on conflict (namespace_id, key, segment_index, locale)
do update set value = excluded.value, status = 'published', updated_at = now();

insert into cethosweb_i18n_translations (namespace_id, key, segment_index, locale, value, status, updated_by)
select ns.id, v.key, 0, 'kn', v.value, 'published', 'claude-seed'
from cethosweb_i18n_namespaces ns
cross join (values
  ('meta.title', 'ಭಾಷಾ ಮತ್ತು ಸಂಶೋಧನಾ ಪ್ಯಾನೆಲ್ | ಸಂಬಳ ಸಹಿತ ಆರೋಗ್ಯ ಸಂಶೋಧನೆ | Cethos'),
  ('meta.description', 'Cethos ಭಾಷಾ ಮತ್ತು ಸಂಶೋಧನಾ ಪ್ಯಾನೆಲ್‌ಗೆ ಸೇರಿ: ಅನುವಾದಿತ ಆರೋಗ್ಯ ಪ್ರಶ್ನಾವಳಿಗಳನ್ನು ಹೆಚ್ಚು ಸ್ಪಷ್ಟಗೊಳಿಸುವ ಸ್ಥಳೀಯ ಭಾಷಿಕರು ಮತ್ತು ರೋಗಿಗಳೊಂದಿಗೆ ಸಂಬಳ ಸಹಿತ ಆನ್‌ಲೈನ್ ಸಂದರ್ಶನಗಳು ಮತ್ತು ಫೋಕಸ್ ಗುಂಪುಗಳು. ಕ್ಲಿನಿಕಲ್ ಫಲಿತಾಂಶ ಮೌಲ್ಯಮಾಪನಗಳಿಗಾಗಿ ಭಾಷಾ ಮೌಲ್ಯೀಕರಣ ಮತ್ತು ಅರಿವಿನ ಡಿಬ್ರೀಫಿಂಗ್, 150+ ಭಾಷೆಗಳಲ್ಲಿ.'),
  ('hero.breadcrumb_home', 'ಮುಖಪುಟ'),
  ('hero.breadcrumb', 'ಸಂಶೋಧನಾ ಪ್ಯಾನೆಲ್'),
  ('hero.title', 'Cethos ಭಾಷಾ ಮತ್ತು ಸಂಶೋಧನಾ ಪ್ಯಾನೆಲ್'),
  ('hero.subtitle', 'ಪ್ರಪಂಚದಾದ್ಯಂತದ ಸ್ಥಳೀಯ ಭಾಷಿಕರು ಮತ್ತು ರೋಗಿಗಳೊಂದಿಗೆ ಸಂಬಳ ಸಹಿತ ಆನ್‌ಲೈನ್ ಸಂಶೋಧನಾ ಅವಧಿಗಳು — ಪ್ರತಿ ಭಾಷೆಯಲ್ಲೂ ಆರೋಗ್ಯ ಮಾಹಿತಿಯನ್ನು ಹೆಚ್ಚು ಸ್ಪಷ್ಟಗೊಳಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತವೆ.'),
  ('hero.cta_join', 'ಪ್ಯಾನೆಲ್‌ಗೆ ಸೇರಿ'),
  ('hero.cta_learn', 'ಇದು ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ'),
  ('what.title', 'ನಾವು ಏನು ಮಾಡುತ್ತೇವೆ'),
  ('what.p1', 'ಆರೋಗ್ಯ ಪ್ರಶ್ನಾವಳಿಯನ್ನು ಅನುವಾದಿಸಿದಾಗ, ರೋಗಿಗಳು ಅದನ್ನು ನಿಜವಾಗಿಯೂ ಅರ್ಥಮಾಡಿಕೊಳ್ಳುತ್ತಾರೆಯೇ ಎಂದು ಯಾರಾದರೂ ಪರಿಶೀಲಿಸಬೇಕು — ಪ್ರತಿ ಪ್ರಶ್ನೆಯೂ ಸ್ಪಷ್ಟ, ಸಹಜ ಮತ್ತು ಪ್ರತಿ ಭಾಷೆಯಲ್ಲೂ ಒಂದೇ ಅರ್ಥವನ್ನು ನೀಡುತ್ತದೆ ಎಂದು. ಆ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಭಾಷಾ ಮೌಲ್ಯೀಕರಣ ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ, ಮತ್ತು ಅದರ ಕೇಂದ್ರಬಿಂದುವಾಗಿರುವ ಸಂದರ್ಶನಗಳನ್ನು ಅರಿವಿನ ಡಿಬ್ರೀಫಿಂಗ್ ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ.'),
  ('what.p2', 'ಪ್ರಪಂಚದಾದ್ಯಂತದ ವೈದ್ಯಕೀಯ ಸಂಶೋಧನೆಯಲ್ಲಿ ಬಳಸಲಾಗುವ ಕ್ಲಿನಿಕಲ್ ಫಲಿತಾಂಶ ಮೌಲ್ಯಮಾಪನಗಳಿಗಾಗಿ Cethos ಈ ಅವಧಿಗಳನ್ನು ನಡೆಸುತ್ತದೆ. ಇದನ್ನು ಸಾಧ್ಯವಾಗಿಸುವ — ಮತ್ತು ಪೂರ್ಣಗೊಳಿಸುವ ಪ್ರತಿ ಅವಧಿಗೂ ಗೌರವಧನ ಪಡೆಯುವ — ಸ್ಥಳೀಯ ಭಾಷಿಕರು ಹಾಗೂ ರೋಗಿಗಳ ಸಮುದಾಯವೇ ನಮ್ಮ ಸಂಶೋಧನಾ ಪ್ಯಾನೆಲ್.'),
  ('what.card1_title', 'ಸಂದರ್ಶನಗಳು ಮತ್ತು ಫೋಕಸ್ ಗುಂಪುಗಳು'),
  ('what.card1_body', 'ಒಬ್ಬರ ಜೊತೆ ಒಬ್ಬರ ಸಂದರ್ಶನಗಳು ಮತ್ತು ಸಣ್ಣ ಗುಂಪು ಅವಧಿಗಳು, ವೀಡಿಯೊ ಕರೆ ಅಥವಾ ದೂರವಾಣಿ ಮೂಲಕ ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ನಡೆಯುತ್ತವೆ. ಹೆಚ್ಚಿನ ಅವಧಿಗಳು 30–90 ನಿಮಿಷಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳುತ್ತವೆ ಮತ್ತು ನಿಮ್ಮ ಭಾಷೆಯಲ್ಲಿ ಅನುಭವಿ ಸಂದರ್ಶಕರಿಂದ ನಡೆಸಲ್ಪಡುತ್ತವೆ.'),
  ('what.card2_title', 'ವಾಸ್ತವ ಜಗತ್ತಿನ ಸ್ಪಷ್ಟತೆ ಪರೀಕ್ಷೆ'),
  ('what.card2_body', 'ನೀವು ಅನುವಾದಿತ ಆರೋಗ್ಯ ಪ್ರಶ್ನೆಗಳನ್ನು ಓದಿ ಅವು ನಿಮ್ಮ ಸ್ವಂತ ಮಾತುಗಳಲ್ಲಿ ಏನನ್ನು ಅರ್ಥೈಸುತ್ತವೆ ಎಂದು ನಮಗೆ ತಿಳಿಸುತ್ತೀರಿ. ಇಲ್ಲಿ ಸರಿ ಅಥವಾ ತಪ್ಪು ಉತ್ತರಗಳಿಲ್ಲ — ಸ್ಥಳೀಯ ಭಾಷಿಕರಾಗಿ ನಿಮ್ಮ ತಿಳುವಳಿಕೆಯೇ ನಾವು ಅಳೆಯುತ್ತಿರುವುದು.'),
  ('what.card3_title', 'ನಿಮ್ಮ ಸಮಯಕ್ಕೆ ಸಂಬಳ'),
  ('what.card3_body', 'ಪ್ರತಿ ಪೂರ್ಣಗೊಂಡ ಅವಧಿಯೂ ಗೌರವಧನ ನೀಡುತ್ತದೆ, ನೀವು ಕಾಯ್ದಿರಿಸುವ ಮೊದಲು ಒಪ್ಪಲಾಗುತ್ತದೆ ಮತ್ತು PayPal ಅಥವಾ ಬ್ಯಾಂಕ್ ವರ್ಗಾವಣೆ ಮೂಲಕ ನಿಮ್ಮ ಸ್ಥಳೀಯ ಕರೆನ್ಸಿಯಲ್ಲಿ, ಸಾಮಾನ್ಯವಾಗಿ 30 ದಿನಗಳ ಒಳಗೆ ಪಾವತಿಸಲಾಗುತ್ತದೆ.'),
  ('how.title', 'ಇದು ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ'),
  ('how.step1_title', 'ಪ್ಯಾನೆಲ್‌ಗೆ ಸೇರಿ'),
  ('how.step1_body', 'ನಿಮ್ಮ ಸ್ವಂತ ಭಾಷೆಯಲ್ಲಿ ಒಮ್ಮೆ ಸೈನ್ ಅಪ್ ಮಾಡಿ. ಇದಕ್ಕೆ ಸುಮಾರು 5 ನಿಮಿಷಗಳು ಬೇಕಾಗುತ್ತವೆ — ನಿಮ್ಮ ಮಾತೃಭಾಷೆ, ನೀವು ವಾಸಿಸುವ ಸ್ಥಳ ಮತ್ತು ನೀವು ಯಾವಾಗ ಲಭ್ಯವಿರುತ್ತೀರಿ ಎಂಬುದನ್ನು ನಮಗೆ ತಿಳಿಸಿ.'),
  ('how.step2_title', 'ಆಹ್ವಾನ ಪಡೆಯಿರಿ'),
  ('how.step2_body', 'ಒಂದು ಅಧ್ಯಯನ ನಿಮ್ಮ ಭಾಷೆ ಮತ್ತು ದೇಶಕ್ಕೆ ಹೊಂದಿಕೆಯಾದಾಗ, ಗೌರವಧನ ಮತ್ತು ಅವಧಿಯ ಉದ್ದವನ್ನು ಮುಂಚಿತವಾಗಿಯೇ ತಿಳಿಸಿ ನಾವು ನಿಮಗೆ ವೈಯಕ್ತಿಕ ಆಹ್ವಾನವನ್ನು ಇಮೇಲ್ ಮಾಡುತ್ತೇವೆ.'),
  ('how.step3_title', 'ಒಂದು ಸಮಯವನ್ನು ಕಾಯ್ದಿರಿಸಿ'),
  ('how.step3_body', 'ನಿಮಗೆ ಸೂಕ್ತವಾದ ಸಮಯ ಸ್ಲಾಟ್ ಅನ್ನು ಆಯ್ಕೆಮಾಡಿ — ಸಮಯಗಳನ್ನು ನಿಮ್ಮ ಸ್ವಂತ ಸಮಯವಲಯದಲ್ಲಿ ತೋರಿಸಲಾಗುತ್ತದೆ. ದೃಢೀಕರಣ, ಸಭೆಯ ಲಿಂಕ್ ಮತ್ತು ಜ್ಞಾಪನೆಗಳು ಎಲ್ಲವೂ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಬರುತ್ತವೆ.'),
  ('how.step4_title', 'ಭಾಗವಹಿಸಿ ಮತ್ತು ಸಂಬಳ ಪಡೆಯಿರಿ'),
  ('how.step4_body', 'ಅವಧಿಗೆ ಸೇರಿ, ನಿಮ್ಮ ದೃಷ್ಟಿಕೋನವನ್ನು ಹಂಚಿಕೊಳ್ಳಿ ಮತ್ತು ನಿಮ್ಮ ಗೌರವಧನವನ್ನು ಪಡೆಯಿರಿ. ಯಾವುದೇ ಸಿದ್ಧತೆ ಮತ್ತು ಯಾವುದೇ ವಿಶೇಷ ಜ್ಞಾನದ ಅಗತ್ಯವಿಲ್ಲ.'),
  ('how.note', 'ಭಾಗವಹಿಸುವಿಕೆ ಯಾವಾಗಲೂ ಸ್ವಯಂಪ್ರೇರಿತ — ನೀವು ಯಾವುದೇ ಆಹ್ವಾನವನ್ನು ನಿರಾಕರಿಸಬಹುದು ಅಥವಾ ಕಾಯ್ದಿರಿಸುವಿಕೆಯನ್ನು ರದ್ದುಗೊಳಿಸಬಹುದು, ಮತ್ತು ಇದು ಎಂದಿಗೂ ಭವಿಷ್ಯದ ಆಹ್ವಾನಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುವುದಿಲ್ಲ.'),
  ('who.title', 'ನಾವು ಯಾರನ್ನು ಹುಡುಕುತ್ತಿದ್ದೇವೆ'),
  ('who.intro', 'ಈ ಪ್ಯಾನೆಲ್ ಪ್ರಪಂಚದಾದ್ಯಂತ ಮುಕ್ತವಾಗಿದೆ ಮತ್ತು ಪ್ರತಿ ವಾರ ಬೆಳೆಯುತ್ತಿದೆ. ಮೂರು ವಿಧದ ಸದಸ್ಯರು ನಮ್ಮ ಅಧ್ಯಯನಗಳನ್ನು ಕಾರ್ಯರೂಪಕ್ಕೆ ತರುತ್ತಾರೆ:'),
  ('who.item1_title', 'ಸ್ಥಳೀಯ ಭಾಷಿಕರು'),
  ('who.item1_body', 'ನಮ್ಮ ಅಧ್ಯಯನ ಭಾಷೆಗಳಲ್ಲಿ ಒಂದನ್ನು ಮಾತೃಭಾಷೆಯಾಗಿ ಮಾತನಾಡುವ ಎಲ್ಲಾ ಹಿನ್ನೆಲೆಯ ವಯಸ್ಕರು. ಯಾವುದೇ ವೈದ್ಯಕೀಯ ಅಥವಾ ಭಾಷಾ ಉದ್ಯಮದ ಅನುಭವದ ಅಗತ್ಯವಿಲ್ಲ — ದೈನಂದಿನ ದೃಷ್ಟಿಕೋನವೇ ಮುಖ್ಯ.'),
  ('who.item2_title', 'ರೋಗಿಗಳು'),
  ('who.item2_body', 'ಅನೇಕ ಅಧ್ಯಯನಗಳು ನಿರ್ದಿಷ್ಟ ಆರೋಗ್ಯ ಸ್ಥಿತಿಯೊಂದಿಗೆ ಬದುಕುತ್ತಿರುವ ಜನರ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸುತ್ತವೆ, ಏಕೆಂದರೆ ಪರೀಕ್ಷಿಸಲಾಗುತ್ತಿರುವ ಪ್ರಶ್ನಾವಳಿಗಳು ಅವರ ಅನುಭವದ ಬಗ್ಗೆ ಇರುತ್ತವೆ. ಆರೋಗ್ಯ ವಿವರಗಳನ್ನು ಹಂಚಿಕೊಳ್ಳುವುದು ಯಾವಾಗಲೂ ಐಚ್ಛಿಕ ಮತ್ತು ಒಪ್ಪಿಗೆ ಆಧಾರಿತವಾಗಿದೆ.'),
  ('who.item3_title', 'ಸಂದರ್ಶಕರು ಮತ್ತು ಸಮುದಾಯ ನೇಮಕಾತಿದಾರರು'),
  ('who.item3_body', 'ಅನುಭವಿ ಅರಿವಿನ ಡಿಬ್ರೀಫಿಂಗ್ ಸಂದರ್ಶಕರು, ಮತ್ತು ಪ್ರತಿ ಭಾಗವಹಿಸುವವರಿಗೆ ಗೌರವಧನಕ್ಕಾಗಿ ಭಾಗವಹಿಸುವವರನ್ನು ಪರಿಚಯಿಸಬಲ್ಲ ಬಲವಾದ ಸಮುದಾಯ ಜಾಲಗಳಿರುವ ಜನರು.'),
  ('roadmap.title', 'ಈ ಕಾರ್ಯಕ್ರಮ ಎಲ್ಲಿಗೆ ಸಾಗುತ್ತಿದೆ'),
  ('roadmap.p1', 'ನಮ್ಮ ಭಾಷಾ ಮೌಲ್ಯೀಕರಣ ಅಧ್ಯಯನಗಳು 150+ ಭಾಷೆಗಳಲ್ಲಿ ನಡೆಯುತ್ತವೆ, ಮತ್ತು ನಾವು ಅದಕ್ಕೆ ಹೊಂದುವಂತೆ ಪ್ಯಾನೆಲ್ ಅನ್ನು — ದೀರ್ಘಕಾಲಿಕ ಸಂಶೋಧನಾ ಸಮುದಾಯವಾಗಿ — ನಿರ್ಮಿಸುತ್ತಿದ್ದೇವೆ:'),
  ('roadmap.item1', 'ಹೆಚ್ಚಿನ ಭಾಷೆಗಳು ಮತ್ತು ದೇಶಗಳು — ಸ್ಪೇನ್‌ಗಾಗಿ ಸ್ಪ್ಯಾನಿಷ್ ವರ್ಸಸ್ ಲ್ಯಾಟಿನ್ ಅಮೆರಿಕದಂತಹ ಪ್ರಾದೇಶಿಕ ರೂಪಾಂತರಗಳನ್ನೂ ಒಳಗೊಂಡು'),
  ('roadmap.item2', 'ಮಧುಮೇಹ ಮತ್ತು ಆಂಕಾಲಜಿಯಿಂದ ಅಪರೂಪದ ರೋಗಗಳವರೆಗೆ, ವಿವಿಧ ಸ್ಥಿತಿಯ ಕ್ಷೇತ್ರಗಳಾದ್ಯಂತ ಹೆಚ್ಚಿನ ರೋಗಿ ಅಧ್ಯಯನಗಳು'),
  ('roadmap.item3', 'ಒಬ್ಬರ ಜೊತೆ ಒಬ್ಬರ ಸಂದರ್ಶನಗಳ ಜೊತೆಗೆ ಫೋಕಸ್ ಗುಂಪುಗಳು, ಸಮಯವಲಯಗಳಾದ್ಯಂತ ನಿಗದಿಪಡಿಸಿದ ಅವಧಿಗಳೊಂದಿಗೆ'),
  ('roadmap.item4', 'ವೇಗವಾದ, ನ್ಯಾಯಯುತ ಗೌರವಧನ ಪಾವತಿಗಳು ಮತ್ತು ನಿಮ್ಮ ಸ್ವಂತ ಭಾಷೆಯಲ್ಲಿ ಸುಗಮ ಕಾಯ್ದಿರಿಸುವ ಅನುಭವ'),
  ('trust.title', 'ನಿಮ್ಮ ಡೇಟಾ, ನಿಮ್ಮ ಆಯ್ಕೆ'),
  ('trust.p1', 'ನಿಮ್ಮನ್ನು ಸೂಕ್ತ ಅಧ್ಯಯನಗಳಿಗೆ ಹೊಂದಿಸಲು ಮತ್ತು ಅವುಗಳ ಬಗ್ಗೆ ನಿಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಲು ಮಾತ್ರ ನೀವು ಹಂಚಿಕೊಳ್ಳುವ ವಿವರಗಳನ್ನು ನಾವು ಸಂಗ್ರಹಿಸುತ್ತೇವೆ. ನಾವು ಎಂದಿಗೂ ನಿಮ್ಮ ಡೇಟಾವನ್ನು ಮಾರಾಟ ಮಾಡುವುದಿಲ್ಲ.'),
  ('trust.p2', 'ಆರೋಗ್ಯ ಮಾಹಿತಿ ಐಚ್ಛಿಕವಾಗಿದೆ, ನಿಮ್ಮ ಸ್ಪಷ್ಟ ಒಪ್ಪಿಗೆಯೊಂದಿಗೆ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು ವಿನಂತಿಯ ಮೇರೆಗೆ ಯಾವಾಗ ಬೇಕಾದರೂ ಅಳಿಸಬಹುದು.'),
  ('trust.p3', 'ಕಾರ್ಯಕ್ರಮ ಅಥವಾ ನಿಮ್ಮ ಡೇಟಾದ ಬಗ್ಗೆ ಪ್ರಶ್ನೆಗಳಿವೆಯೇ? lv@cethos.com ನಲ್ಲಿ ನಮಗೆ ಬರೆಯಿರಿ.'),
  ('cta.title', 'ಭಾಗವಹಿಸಲು ಸಿದ್ಧರಿದ್ದೀರಾ?'),
  ('cta.body', 'ಸೈನ್ ಅಪ್ ಮಾಡಲು ಸುಮಾರು 5 ನಿಮಿಷಗಳು ಬೇಕಾಗುತ್ತವೆ, ಮತ್ತು ಒಂದು ಅಧ್ಯಯನ ನಿಜವಾಗಿಯೂ ನಿಮಗೆ ಹೊಂದಿಕೆಯಾದಾಗ ಮಾತ್ರ ನೀವು ನಮ್ಮಿಂದ ಕೇಳುತ್ತೀರಿ.'),
  ('cta.button', 'ಸಂಶೋಧನಾ ಪ್ಯಾನೆಲ್‌ಗೆ ಸೇರಿ'),
  ('cta.sponsor_title', 'ಭಾಷಾ ಮೌಲ್ಯೀಕರಣ ಅಧ್ಯಯನವನ್ನು ನಡೆಸುತ್ತಿದ್ದೀರಾ?'),
  ('cta.sponsor_body', 'ಪ್ರಾಯೋಜಕರು ಮತ್ತು CRO ಗಳು: ನಾವು ಅನುಭವಿ ಅರಿವಿನ ಡಿಬ್ರೀಫಿಂಗ್ ಸಂದರ್ಶಕರು ಮತ್ತು ಆದ್ಯಂತ ಸಮನ್ವಯದೊಂದಿಗೆ, 150+ ಭಾಷೆಗಳಾದ್ಯಂತ ನೇಮಕ ಮಾಡುತ್ತೇವೆ, ವೇಳಾಪಟ್ಟಿ ಸಿದ್ಧಪಡಿಸುತ್ತೇವೆ ಮತ್ತು ಸಂದರ್ಶನ ನಡೆಸುತ್ತೇವೆ.'),
  ('cta.sponsor_button', 'ನಮ್ಮ ತಂಡದೊಂದಿಗೆ ಮಾತನಾಡಿ')
) as v(key, value)
where ns.name = 'research'
on conflict (namespace_id, key, segment_index, locale)
do update set value = excluded.value, status = 'published', updated_at = now();

insert into cethosweb_i18n_translations (namespace_id, key, segment_index, locale, value, status, updated_by)
select ns.id, v.key, 0, 'ta', v.value, 'published', 'claude-seed'
from cethosweb_i18n_namespaces ns
cross join (values
  ('meta.title', 'மொழி மற்றும் ஆய்வுக் குழு | ஊதியம் பெறும் சுகாதார ஆய்வு | Cethos'),
  ('meta.description', 'Cethos மொழி மற்றும் ஆய்வுக் குழுவில் சேரவும்: மொழிபெயர்க்கப்பட்ட சுகாதார கேள்வித்தாள்களைத் தெளிவாக்கும் தாய்மொழி பேசுபவர்கள் மற்றும் நோயாளிகளுடன் ஊதியம் பெறும் ஆன்லைன் நேர்காணல்கள் மற்றும் கருத்துக் குழுக்கள். மருத்துவ முடிவு மதிப்பீடுகளுக்கான மொழியியல் சரிபார்ப்பு மற்றும் அறிவாற்றல் விளக்கவுரை, 150+ மொழிகளில்.'),
  ('hero.breadcrumb_home', 'முகப்பு'),
  ('hero.breadcrumb', 'ஆய்வுக் குழு'),
  ('hero.title', 'Cethos மொழி மற்றும் ஆய்வுக் குழு'),
  ('hero.subtitle', 'உலகெங்கிலும் உள்ள தாய்மொழி பேசுபவர்கள் மற்றும் நோயாளிகளுடன் ஊதியம் பெறும் ஆன்லைன் ஆய்வு அமர்வுகள் — ஒவ்வொரு மொழியிலும் சுகாதார தகவல்களைத் தெளிவாக்க உதவுகிறது.'),
  ('hero.cta_join', 'குழுவில் சேரவும்'),
  ('hero.cta_learn', 'இது எப்படி வேலை செய்கிறது'),
  ('what.title', 'நாங்கள் என்ன செய்கிறோம்'),
  ('what.p1', 'ஒரு சுகாதார கேள்வித்தாள் மொழிபெயர்க்கப்படும்போது, நோயாளிகள் அதை உண்மையிலேயே புரிந்துகொள்கிறார்களா என்பதை — ஒவ்வொரு கேள்வியும் தெளிவாகவும், இயல்பாகவும் இருக்கிறதா, ஒவ்வொரு மொழியிலும் ஒரே பொருளைத் தருகிறதா என்பதை — யாராவது சரிபார்க்க வேண்டும். அந்தச் செயல்முறை மொழியியல் சரிபார்ப்பு எனப்படுகிறது, அதன் மையத்தில் உள்ள நேர்காணல்கள் அறிவாற்றல் விளக்கவுரை எனப்படுகின்றன.'),
  ('what.p2', 'உலகெங்கிலும் உள்ள மருத்துவ ஆய்வில் பயன்படுத்தப்படும் மருத்துவ முடிவு மதிப்பீடுகளுக்காக Cethos இந்த அமர்வுகளை நடத்துகிறது. எங்கள் ஆய்வுக் குழு என்பது அதைச் சாத்தியமாக்கும் தாய்மொழி பேசுபவர்கள் மற்றும் நோயாளிகளின் சமூகம் — மேலும் அவர்கள் முடிக்கும் ஒவ்வொரு அமர்வுக்கும் ஒரு பொருட்செலவு தொகை வழங்கப்படுகிறது.'),
  ('what.card1_title', 'நேர்காணல்கள் மற்றும் கருத்துக் குழுக்கள்'),
  ('what.card1_body', 'ஒருவருக்கொருவர் நேர்காணல்கள் மற்றும் சிறு குழு அமர்வுகள், வீடியோ அழைப்பு அல்லது தொலைபேசி மூலம் ஆன்லைனில் நடத்தப்படுகின்றன. பெரும்பாலான அமர்வுகள் 30–90 நிமிடங்கள் ஆகும், உங்கள் மொழியில் அனுபவமிக்க நேர்காணல் நடத்துபவரால் வழிநடத்தப்படுகின்றன.'),
  ('what.card2_title', 'நிஜ உலகத் தெளிவுச் சோதனை'),
  ('what.card2_body', 'நீங்கள் மொழிபெயர்க்கப்பட்ட சுகாதார கேள்விகளைப் படித்து, அவை உங்கள் சொந்த வார்த்தைகளில் என்ன அர்த்தம் என்பதை எங்களிடம் சொல்கிறீர்கள். சரி அல்லது தவறான பதில்கள் எதுவும் இல்லை — தாய்மொழி பேசுபவராக உங்கள் புரிதலே நாங்கள் அளவிடுவது.'),
  ('what.card3_title', 'உங்கள் நேரத்திற்கு ஊதியம்'),
  ('what.card3_body', 'முடிக்கப்பட்ட ஒவ்வொரு அமர்வும் ஒரு பொருட்செலவு தொகையை வழங்குகிறது, நீங்கள் முன்பதிவு செய்வதற்கு முன் ஒப்புக்கொள்ளப்பட்டு, உங்கள் உள்ளூர் நாணயத்தில் PayPal அல்லது வங்கிப் பரிமாற்றம் மூலம், பொதுவாக 30 நாட்களுக்குள் செலுத்தப்படுகிறது.'),
  ('how.title', 'இது எப்படி வேலை செய்கிறது'),
  ('how.step1_title', 'குழுவில் சேரவும்'),
  ('how.step1_body', 'உங்கள் சொந்த மொழியில், ஒரு முறை பதிவு செய்யுங்கள். இதற்கு சுமார் 5 நிமிடங்கள் ஆகும் — உங்கள் தாய்மொழி, நீங்கள் வசிக்கும் இடம், நீங்கள் எப்போது கிடைப்பீர்கள் என்பதை எங்களிடம் சொல்லுங்கள்.'),
  ('how.step2_title', 'அழைப்பு பெறுங்கள்'),
  ('how.step2_body', 'ஒரு ஆய்வு உங்கள் மொழி மற்றும் நாட்டுடன் பொருந்தும்போது, பொருட்செலவு தொகை மற்றும் அமர்வு நீளத்துடன் ஒரு தனிப்பட்ட அழைப்பை உங்களுக்கு மின்னஞ்சல் அனுப்புகிறோம்.'),
  ('how.step3_title', 'ஒரு நேரத்தை முன்பதிவு செய்யுங்கள்'),
  ('how.step3_body', 'உங்களுக்கு ஏற்ற ஒரு நேர இடத்தைத் தேர்ந்தெடுக்கவும் — நேரங்கள் உங்கள் சொந்த நேர மண்டலத்தில் காட்டப்படுகின்றன. உறுதிப்படுத்தல், சந்திப்பு இணைப்பு மற்றும் நினைவூட்டல்கள் அனைத்தும் தானாகவே வரும்.'),
  ('how.step4_title', 'பங்கேற்று ஊதியம் பெறுங்கள்'),
  ('how.step4_body', 'அமர்வில் சேர்ந்து, உங்கள் பார்வையைப் பகிர்ந்து, உங்கள் பொருட்செலவு தொகையைப் பெறுங்கள். எந்தத் தயாரிப்பும் சிறப்பு அறிவும் தேவையில்லை.'),
  ('how.note', 'பங்கேற்பது எப்போதும் தன்னார்வமானது — நீங்கள் எந்த அழைப்பையும் மறுக்கலாம் அல்லது ஒரு முன்பதிவை ரத்து செய்யலாம், அது எதிர்கால அழைப்புகளை ஒருபோதும் பாதிக்காது.'),
  ('who.title', 'நாங்கள் யாரைத் தேடுகிறோம்'),
  ('who.intro', 'இந்தக் குழு உலகம் முழுவதும் திறந்திருக்கிறது, ஒவ்வொரு வாரமும் வளர்கிறது. மூன்று வகையான உறுப்பினர்கள் எங்கள் ஆய்வுகளை வேலை செய்ய வைக்கிறார்கள்:'),
  ('who.item1_title', 'தாய்மொழி பேசுபவர்கள்'),
  ('who.item1_body', 'எங்கள் ஆய்வு மொழிகளில் ஒன்றை தாய்மொழியாகப் பேசும் அனைத்துப் பின்னணிகளையும் சேர்ந்த பெரியவர்கள். மருத்துவ அல்லது மொழித் துறை அனுபவம் தேவையில்லை — அன்றாட பார்வையே முக்கியம்.'),
  ('who.item2_title', 'நோயாளிகள்'),
  ('who.item2_body', 'பல ஆய்வுகள் ஒரு குறிப்பிட்ட உடல்நல நிலையுடன் வாழும் மக்களை மையமாகக் கொண்டுள்ளன, ஏனெனில் சோதிக்கப்படும் கேள்வித்தாள்கள் அவர்களின் அனுபவம் பற்றியவை. சுகாதார விவரங்களைப் பகிர்வது எப்போதும் விருப்பமானது மற்றும் ஒப்புதலின் அடிப்படையிலானது.'),
  ('who.item3_title', 'நேர்காணல் நடத்துபவர்கள் மற்றும் சமூக ஆட்சேர்ப்பாளர்கள்'),
  ('who.item3_body', 'அனுபவமிக்க அறிவாற்றல்-விளக்கவுரை நேர்காணல் நடத்துபவர்கள், மற்றும் ஒரு பங்கேற்பாளருக்கு ஒரு பொருட்செலவு தொகைக்காக பங்கேற்பாளர்களை அறிமுகப்படுத்தக்கூடிய வலுவான சமூக வலையமைப்புகளைக் கொண்டவர்கள்.'),
  ('roadmap.title', 'இந்தத் திட்டம் எங்கு செல்கிறது'),
  ('roadmap.p1', 'எங்கள் மொழியியல் சரிபார்ப்பு ஆய்வுகள் 150+ மொழிகளில் நடைபெறுகின்றன, அதற்கு ஏற்ப நாங்கள் இந்தக் குழுவை — ஒரு நீண்டகால ஆய்வுச் சமூகமாக — உருவாக்கி வருகிறோம்:'),
  ('roadmap.item1', 'மேலும் மொழிகள் மற்றும் நாடுகள் — ஸ்பெயினுக்கான ஸ்பானிஷ் மற்றும் லத்தீன் அமெரிக்காவுக்கானது போன்ற பிராந்திய வகைகள் உட்பட'),
  ('roadmap.item2', 'நீரிழிவு மற்றும் புற்றுநோயியல் முதல் அரிய நோய்கள் வரை, நிலைப் பகுதிகள் முழுவதும் மேலும் நோயாளி ஆய்வுகள்'),
  ('roadmap.item3', 'ஒருவருக்கொருவர் நேர்காணல்களுடன் கருத்துக் குழுக்கள், நேர மண்டலங்கள் முழுவதும் அமர்வுகள் திட்டமிடப்பட்டுள்ளன'),
  ('roadmap.item4', 'வேகமான, நியாயமான பொருட்செலவு தொகை பணம் மற்றும் உங்கள் சொந்த மொழியில் மென்மையான முன்பதிவு அனுபவம்'),
  ('trust.title', 'உங்கள் தரவு, உங்கள் தேர்வு'),
  ('trust.p1', 'பொருத்தமான ஆய்வுகளுடன் உங்களைப் பொருத்துவதற்கும், அவற்றைப் பற்றி உங்களைத் தொடர்பு கொள்வதற்கும் மட்டுமே நீங்கள் பகிரும் விவரங்களைச் சேமிக்கிறோம். உங்கள் தரவை நாங்கள் ஒருபோதும் விற்பதில்லை.'),
  ('trust.p2', 'சுகாதார தகவல் விருப்பமானது, உங்கள் வெளிப்படையான ஒப்புதலுடன் சேமிக்கப்படுகிறது, கோரிக்கையின் பேரில் எந்த நேரத்திலும் நீக்கப்படலாம்.'),
  ('trust.p3', 'திட்டம் அல்லது உங்கள் தரவு பற்றிய கேள்விகளா? lv@cethos.com இல் எங்களுக்கு எழுதுங்கள்.'),
  ('cta.title', 'பங்கேற்கத் தயாரா?'),
  ('cta.body', 'பதிவு செய்ய சுமார் 5 நிமிடங்கள் ஆகும், ஒரு ஆய்வு உண்மையிலேயே உங்களுடன் பொருந்தும்போது மட்டுமே நீங்கள் எங்களிடமிருந்து கேள்விப்படுவீர்கள்.'),
  ('cta.button', 'ஆய்வுக் குழுவில் சேரவும்'),
  ('cta.sponsor_title', 'ஒரு மொழியியல் சரிபார்ப்பு ஆய்வை நடத்துகிறீர்களா?'),
  ('cta.sponsor_body', 'ஸ்பான்சர்கள் மற்றும் CROக்கள்: அனுபவமிக்க அறிவாற்றல்-விளக்கவுரை நேர்காணல் நடத்துபவர்கள் மற்றும் முழுமையான ஒருங்கிணைப்புடன், 150+ மொழிகளில் நாங்கள் ஆட்சேர்ப்பு செய்து, அட்டவணைப்படுத்தி, நேர்காணல் செய்கிறோம்.'),
  ('cta.sponsor_button', 'எங்கள் குழுவுடன் பேசுங்கள்')
) as v(key, value)
where ns.name = 'research'
on conflict (namespace_id, key, segment_index, locale)
do update set value = excluded.value, status = 'published', updated_at = now();

insert into cethosweb_i18n_translations (namespace_id, key, segment_index, locale, value, status, updated_by)
select ns.id, v.key, 0, 'te', v.value, 'published', 'claude-seed'
from cethosweb_i18n_namespaces ns
cross join (values
  ('meta.title', 'భాషా & పరిశోధన ప్యానెల్ | చెల్లింపుతో కూడిన ఆరోగ్య పరిశోధన | Cethos'),
  ('meta.description', 'Cethos భాషా & పరిశోధన ప్యానెల్‌లో చేరండి: అనువదించిన ఆరోగ్య ప్రశ్నావళులను మరింత స్పష్టంగా చేసేందుకు స్థానిక భాషీయులు మరియు రోగులతో చెల్లింపుతో కూడిన ఆన్‌లైన్ ఇంటర్వ్యూలు, ఫోకస్ గ్రూప్‌లు. క్లినికల్ ఔట్‌కమ్ అసెస్‌మెంట్‌ల కోసం భాషాపరమైన ధ్రువీకరణ మరియు కాగ్నిటివ్ డీబ్రీఫింగ్, 150+ భాషల్లో.'),
  ('hero.breadcrumb_home', 'హోమ్'),
  ('hero.breadcrumb', 'పరిశోధన ప్యానెల్'),
  ('hero.title', 'Cethos భాషా & పరిశోధన ప్యానెల్'),
  ('hero.subtitle', 'ప్రపంచవ్యాప్తంగా ఉన్న స్థానిక భాషీయులు మరియు రోగులతో చెల్లింపుతో కూడిన ఆన్‌లైన్ పరిశోధన సెషన్‌లు — ప్రతి భాషలోనూ ఆరోగ్య సమాచారాన్ని మరింత స్పష్టంగా చేసేందుకు సహాయపడతాయి.'),
  ('hero.cta_join', 'ప్యానెల్‌లో చేరండి'),
  ('hero.cta_learn', 'ఇది ఎలా పనిచేస్తుంది'),
  ('what.title', 'మేము ఏం చేస్తాము'),
  ('what.p1', 'ఒక ఆరోగ్య ప్రశ్నావళి అనువదించబడినప్పుడు, రోగులు దాన్ని నిజంగా అర్థం చేసుకుంటున్నారా అని ఎవరో ఒకరు తనిఖీ చేయాలి — ప్రతి ప్రశ్నా స్పష్టంగా, సహజంగా ఉందా, మరియు ప్రతి భాషలోనూ ఒకే అర్థాన్ని ఇస్తోందా అని. ఆ ప్రక్రియను భాషాపరమైన ధ్రువీకరణ అంటారు, మరియు దాని కేంద్రంలో ఉండే ఇంటర్వ్యూలను కాగ్నిటివ్ డీబ్రీఫింగ్ అంటారు.'),
  ('what.p2', 'ప్రపంచవ్యాప్తంగా వైద్య పరిశోధనలో ఉపయోగించే క్లినికల్ ఔట్‌కమ్ అసెస్‌మెంట్‌ల కోసం Cethos ఈ సెషన్‌లను నిర్వహిస్తుంది. మా పరిశోధన ప్యానెల్ అంటే దీన్ని సాధ్యం చేసే స్థానిక భాషీయులు మరియు రోగుల సముదాయం — వారు పూర్తి చేసే ప్రతి సెషన్‌కూ వారికి గౌరవ వేతనం చెల్లించబడుతుంది.'),
  ('what.card1_title', 'ఇంటర్వ్యూలు & ఫోకస్ గ్రూప్‌లు'),
  ('what.card1_body', 'వీడియో కాల్ ద్వారా లేదా ఫోన్ ద్వారా ఆన్‌లైన్‌లో నిర్వహించే వ్యక్తిగత ఇంటర్వ్యూలు మరియు చిన్న గ్రూప్ సెషన్‌లు. చాలా సెషన్‌లు 30–90 నిమిషాలు జరుగుతాయి మరియు మీ భాషలో అనుభవజ్ఞుడైన ఇంటర్వ్యూయర్ ద్వారా నిర్వహించబడతాయి.'),
  ('what.card2_title', 'వాస్తవ ప్రపంచపు స్పష్టత పరీక్ష'),
  ('what.card2_body', 'మీరు అనువదించిన ఆరోగ్య ప్రశ్నలను చదివి, అవి మీకు ఏమని అర్థమవుతున్నాయో మీ స్వంత మాటల్లో మాకు చెబుతారు. ఇక్కడ సరైన లేదా తప్పు సమాధానాలు అంటూ ఏవీ లేవు — స్థానిక భాషీయుడిగా మీ అవగాహనే మేము కొలుస్తున్నది.'),
  ('what.card3_title', 'మీ సమయానికి చెల్లింపు'),
  ('what.card3_body', 'పూర్తయిన ప్రతి సెషన్‌కూ గౌరవ వేతనం చెల్లించబడుతుంది, మీరు బుక్ చేసుకునే ముందే అంగీకరించబడుతుంది మరియు మీ స్థానిక కరెన్సీలో PayPal లేదా బ్యాంక్ బదిలీ ద్వారా, సాధారణంగా 30 రోజుల్లోగా చెల్లించబడుతుంది.'),
  ('how.title', 'ఇది ఎలా పనిచేస్తుంది'),
  ('how.step1_title', 'ప్యానెల్‌లో చేరండి'),
  ('how.step1_body', 'మీ స్వంత భాషలో ఒకసారి సైన్ అప్ చేయండి. దీనికి దాదాపు 5 నిమిషాలు పడుతుంది — మీ మాతృభాష, మీరు నివసించే ప్రదేశం, మరియు మీకు అందుబాటులో ఉండే సమయాలను మాకు తెలియజేయండి.'),
  ('how.step2_title', 'ఆహ్వానం పొందండి'),
  ('how.step2_body', 'ఒక అధ్యయనం మీ భాష మరియు దేశానికి సరిపోయినప్పుడు, గౌరవ వేతనం మరియు సెషన్ నిడివిని ముందుగానే తెలియజేస్తూ మేము మీకు వ్యక్తిగత ఆహ్వానాన్ని ఇమెయిల్ చేస్తాము.'),
  ('how.step3_title', 'సమయాన్ని బుక్ చేసుకోండి'),
  ('how.step3_body', 'మీకు అనుకూలమైన సమయాన్ని ఎంచుకోండి — సమయాలు మీ స్వంత టైమ్‌జోన్‌లో చూపబడతాయి. నిర్ధారణ, మీటింగ్ లింక్, మరియు రిమైండర్‌లు అన్నీ ఆటోమేటిక్‌గా వస్తాయి.'),
  ('how.step4_title', 'పాల్గొని చెల్లింపు పొందండి'),
  ('how.step4_body', 'సెషన్‌లో చేరండి, మీ దృక్కోణాన్ని పంచుకోండి, మరియు మీ గౌరవ వేతనాన్ని పొందండి. ఎటువంటి సన్నాహం లేదా ప్రత్యేక పరిజ్ఞానం అవసరం లేదు.'),
  ('how.note', 'పాల్గొనడం ఎప్పుడూ స్వచ్ఛందమే — మీరు ఏ ఆహ్వానాన్నైనా తిరస్కరించవచ్చు లేదా బుకింగ్‌ను రద్దు చేసుకోవచ్చు, మరియు అది భవిష్యత్ ఆహ్వానాలపై ఎప్పటికీ ప్రభావం చూపదు.'),
  ('who.title', 'మేము ఎవరి కోసం వెతుకుతున్నాము'),
  ('who.intro', 'ఈ ప్యానెల్ ప్రపంచవ్యాప్తంగా అందరికీ తెరిచి ఉంది మరియు ప్రతి వారం పెరుగుతోంది. మా అధ్యయనాలు పనిచేయడానికి మూడు రకాల సభ్యులు దోహదం చేస్తారు:'),
  ('who.item1_title', 'స్థానిక భాషీయులు'),
  ('who.item1_body', 'మా అధ్యయన భాషల్లో ఒకదాన్ని మాతృభాషగా మాట్లాడే అన్ని నేపథ్యాల వయోజనులు. ఎటువంటి వైద్య లేదా భాషా-పరిశ్రమ అనుభవం అవసరం లేదు — రోజువారీ దృక్కోణమే ముఖ్యం.'),
  ('who.item2_title', 'రోగులు'),
  ('who.item2_body', 'చాలా అధ్యయనాలు ఒక నిర్దిష్ట ఆరోగ్య పరిస్థితితో జీవిస్తున్న వ్యక్తులపై దృష్టి పెడతాయి, ఎందుకంటే పరీక్షించబడుతున్న ప్రశ్నావళులు వారి అనుభవానికి సంబంధించినవి. ఆరోగ్య వివరాలను పంచుకోవడం ఎప్పుడూ ఐచ్ఛికం మరియు సమ్మతి ఆధారితం.'),
  ('who.item3_title', 'ఇంటర్వ్యూయర్‌లు & సముదాయ రిక్రూటర్‌లు'),
  ('who.item3_body', 'అనుభవజ్ఞులైన కాగ్నిటివ్-డీబ్రీఫింగ్ ఇంటర్వ్యూయర్‌లు, మరియు ఒక్కో పాల్గొనేవారికి గౌరవ వేతనం కోసం పాల్గొనేవారిని పరిచయం చేయగల బలమైన సముదాయ నెట్‌వర్క్‌లు ఉన్న వ్యక్తులు.'),
  ('roadmap.title', 'ఈ కార్యక్రమం ఎటువైపు వెళ్తోంది'),
  ('roadmap.p1', 'మా భాషాపరమైన ధ్రువీకరణ అధ్యయనాలు 150+ భాషల్లో జరుగుతాయి, మరియు దీనికి సరిపోయేలా — దీర్ఘకాలిక పరిశోధన సముదాయంగా — మేము ప్యానెల్‌ను నిర్మిస్తున్నాము:'),
  ('roadmap.item1', 'మరిన్ని భాషలు మరియు దేశాలు — స్పెయిన్‌కు సంబంధించిన స్పానిష్ మరియు లాటిన్ అమెరికాకు సంబంధించిన స్పానిష్ వంటి ప్రాంతీయ రూపాంతరాలతో సహా'),
  ('roadmap.item2', 'డయాబెటిస్ మరియు ఆంకాలజీ నుండి అరుదైన వ్యాధుల వరకు, వివిధ పరిస్థితుల విభాగాల్లో మరిన్ని రోగి అధ్యయనాలు'),
  ('roadmap.item3', 'వ్యక్తిగత ఇంటర్వ్యూలతో పాటు ఫోకస్ గ్రూప్‌లు, వివిధ టైమ్‌జోన్‌లలో షెడ్యూల్ చేయబడిన సెషన్‌లతో'),
  ('roadmap.item4', 'వేగవంతమైన, మరింత న్యాయమైన గౌరవ వేతన చెల్లింపులు మరియు మీ స్వంత భాషలో సున్నితమైన బుకింగ్ అనుభవం'),
  ('trust.title', 'మీ డేటా, మీ ఎంపిక'),
  ('trust.p1', 'మీకు సరిపోయే అధ్యయనాలతో మిమ్మల్ని జతచేయడానికి మరియు వాటి గురించి మిమ్మల్ని సంప్రదించడానికి మాత్రమే మీరు పంచుకునే వివరాలను మేము నిల్వ చేస్తాము. మేము మీ డేటాను ఎప్పటికీ అమ్మము.'),
  ('trust.p2', 'ఆరోగ్య సమాచారం ఐచ్ఛికం, మీ స్పష్టమైన సమ్మతితో నిల్వ చేయబడుతుంది, మరియు అభ్యర్థనపై ఎప్పుడైనా తొలగించవచ్చు.'),
  ('trust.p3', 'ఈ కార్యక్రమం లేదా మీ డేటా గురించి ప్రశ్నలా? lv@cethos.com కు మాకు రాయండి.'),
  ('cta.title', 'పాల్గొనడానికి సిద్ధంగా ఉన్నారా?'),
  ('cta.body', 'సైన్ అప్ చేయడానికి దాదాపు 5 నిమిషాలు పడుతుంది, మరియు ఒక అధ్యయనం నిజంగా మీకు సరిపోయినప్పుడు మాత్రమే మీరు మా నుండి వింటారు.'),
  ('cta.button', 'పరిశోధన ప్యానెల్‌లో చేరండి'),
  ('cta.sponsor_title', 'భాషాపరమైన ధ్రువీకరణ అధ్యయనాన్ని నిర్వహిస్తున్నారా?'),
  ('cta.sponsor_body', 'స్పాన్సర్‌లు మరియు CROలు: మేము 150+ భాషల్లో రిక్రూట్ చేస్తాము, షెడ్యూల్ చేస్తాము, మరియు ఇంటర్వ్యూ చేస్తాము, అనుభవజ్ఞులైన కాగ్నిటివ్-డీబ్రీఫింగ్ ఇంటర్వ్యూయర్‌లు మరియు సమగ్ర సమన్వయంతో.'),
  ('cta.sponsor_button', 'మా బృందంతో మాట్లాడండి')
) as v(key, value)
where ns.name = 'research'
on conflict (namespace_id, key, segment_index, locale)
do update set value = excluded.value, status = 'published', updated_at = now();
